import { action, addCommonDatenfelderSearchOptions, choiceOption, commonDatenfelderParams, parseNonEmpty, renderJson, renderRaw, } from "../shared.js";
import { SchemaSucheInValues } from "@maschinenlesbar.org/fim-portal-client/internal/enums";
export function registerSchemaCommands(program, deps) {
    const schemas = program.command("schemas").description("Datenschemata (XDatenfelder)");
    const search = schemas
        .command("search")
        .description("Search/filter Datenschemata")
        .option("--bezug-unterelemente <text>", "filter by Bezug of sub-elements", parseNonEmpty)
        .option("--bezeichnung <text>", "filter by Bezeichnung", parseNonEmpty)
        .option("--stichwort <text>", "filter by Stichwort (XDF3 only)", parseNonEmpty)
        .addOption(choiceOption("--suche-nur-in <module>", "restrict full-text search to a module", SchemaSucheInValues));
    addCommonDatenfelderSearchOptions(search).action(action(deps, async ({ client, global, opts }) => {
        const params = {
            ...commonDatenfelderParams(opts),
            bezug_unterelemente: opts["bezugUnterelemente"],
            bezeichnung: opts["bezeichnung"],
            stichwort: opts["stichwort"],
            suche_nur_in: opts["sucheNurIn"],
        };
        renderJson(deps, global, await client.schemas.search(params));
    }));
    schemas
        .command("versions")
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .description("List all versions of a schema")
        .action(action(deps, async ({ client, global }, [fimId]) => {
        renderJson(deps, global, await client.schemas.versions(fimId));
    }));
    schemas
        .command("get")
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .argument("[fimVersion]", "FIM version (default: latest)", parseNonEmpty)
        .description("Get a full schema (version defaults to 'latest')")
        .action(action(deps, async ({ client, global }, [fimId, fimVersion]) => {
        renderJson(deps, global, await client.schemas.get(fimId, fimVersion ?? "latest"));
    }));
    schemas
        .command("xdf")
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .argument("[fimVersion]", "FIM version (default: latest)", parseNonEmpty)
        .description("Download the XDatenfelder XML for a schema")
        .action(action(deps, async ({ client, global }, [fimId, fimVersion]) => {
        await renderRaw(deps, global, await client.schemas.downloadXdf(fimId, fimVersion ?? "latest"));
    }));
    schemas
        .command("quality-report")
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .argument("[fimVersion]", "FIM version (default: latest)", parseNonEmpty)
        .description("Get the quality report for a schema")
        .action(action(deps, async ({ client, global }, [fimId, fimVersion]) => {
        renderJson(deps, global, await client.schemas.qualityReport(fimId, fimVersion ?? "latest"));
    }));
}
